do
    local setter = setthreadidentity or setidentity or set_thread_identity
        or setthreadcontext or set_thread_context
    if type(setter) == "function" then
        local ok, err = pcall(setter, 8)
        if not ok then error("[Kyoto] Thread initialization failed: " .. tostring(err), 0) end
    end
end
